-- move id sequences past the sample ids
select setval('public.ledger_id_seq', greatest((select coalesce(max(nullif(regexp_replace(id, '\D', '', 'g'), '')::bigint), 0) from public.ledger where id ~ '\d$'), (select last_value from public.ledger_id_seq)));
